/** SVG or text badge for a product key, as an HTML string. Dark logos use the ink colour so they show in dark mode. */
export function iconHTML(key: string | undefined, size = 18): string {
  if (!key) return "";
  const i = ICONS[key];
  if (i) {
    const h = i.h, r = parseInt(h.slice(0, 2), 16), g = parseInt(h.slice(2, 4), 16), b = parseInt(h.slice(4, 6), 16);
    const dark = 0.2126 * r + 0.7152 * g + 0.0722 * b < 60;
    return `<svg class="ico" width="${size}" height="${size}" viewBox="0 0 24 24" role="img" aria-hidden="true" style="fill:${dark ? "var(--ink)" : "#" + h}"><path d="${i.p}"/></svg>`;
  }
  const bd = BADGES[key];
  if (!bd) return "";
  if (key === "person") return `<svg class="ico" width="${size}" height="${size}" viewBox="0 0 24 24" aria-hidden="true" style="fill:${bd[1]}"><circle cx="12" cy="7" r="4.5"/><path d="M3 22c0-5 4-8 9-8s9 3 9 8z"/></svg>`;
  return `<span class="ico badge" aria-hidden="true" style="--b:${bd[1]};height:${size}px;min-width:${size}px;font-size:${Math.round(size * 0.48)}px">${bd[0]}</span>`;
}
